// Generated by the K6 split: the vertical tire laws and their model parameters,
// moved verbatim out of `kernel_model.cpp`.
//
// This unit owns the vertical half of the tire models -- the Fiala and PAC2002
// startup smoothing, rolling radius, curve interpolation, bottoming, elastic and
// vertical force laws, and the Maxwell element that relaxes with deflection --
// plus the model-parameter readers they share.  It carries no model topology and
// registers nothing.

#include "mb_tire/fiala/functions.hpp"

namespace axle_kernel {

int fiala_use_mode(const Tire& tire) {
    const double raw = std::abs(fiala_parameter(tire, FIALA_USE_MODE, 2.0));
    if (!std::isfinite(raw)) return 2;
    return static_cast<int>(std::lround(raw));
}

bool fiala_startup_smoothing_enabled() {
    const char* value = std::getenv("SUSPENSION_AXLE_FIALA_STARTUP_SMOOTHING");
    return value != nullptr && value[0] != '\0' && value[0] != '0';
}

double fiala_startup_scale(int use_mode, double time) {
    if (!fiala_startup_smoothing_enabled()) return 1.0;
    if (use_mode != 2 && use_mode != 12) return 1.0;
    if (!(time < 0.1)) return 1.0;
    const double u = std::max(0.0, time)/0.1;
    return u*u*(3.0-2.0*u);
}

bool fiala_transient_forced() {
    const char* value = std::getenv("SUSPENSION_AXLE_FIALA_FORCE_TRANSIENT");
    return value != nullptr && value[0] != '\0' && value[0] != '0';
}

bool fiala_transient_enabled(int use_mode) {
    if (fiala_transient_forced()) return true;
    return use_mode == 11 || use_mode == 12;
}

double fiala_rolling_resistance_factor(double spin_rate) {
    const double speed = std::abs(spin_rate);
    if (!(speed > 0.125)) return 0.0;
    if (speed >= 0.5) return -std::copysign(1.0, spin_rate);
    const double u = (speed-0.125)/0.375;
    return -std::copysign(u*u*(3.0-2.0*u), spin_rate);
}

} // namespace axle_kernel
